using Dapper;using FinOS.Common.Interfaces;using FinOS.CoreFinance.Domain.Entities;using FinOS.CoreFinance.Domain.Interfaces;namespace FinOS.CoreFinance.Infrastructure.Repositories;
public class AssetRepository(IConnectionFactory f):IAssetRepository{public async Task<IReadOnlyList<Asset>>GetAsync(long u,CancellationToken ct=default){using var c=f.CreateConnection();return(await c.QueryAsync<Asset>("SELECT * FROM Core.Assets WHERE UserId=@u AND DeletedAt IS NULL ORDER BY CurrentEstimatedValue DESC",new{u})).ToList();}public async Task<Asset>AddAsync(Asset x,CancellationToken ct=default){using var c=f.CreateConnection();x.Id=await c.ExecuteScalarAsync<long>(@"INSERT Core.Assets(UserId,AssetType,Name,PurchaseValue,PurchaseDate,CurrentEstimatedValue,ValuationDate,AssociatedLoanId,Notes)VALUES(@UserId,@AssetType,@Name,@PurchaseValue,@PurchaseDate,@CurrentEstimatedValue,@ValuationDate,@AssociatedLoanId,@Notes);SELECT CAST(SCOPE_IDENTITY() AS BIGINT)",x);return x;}public async Task<bool>DeleteAsync(long id,long u,CancellationToken ct=default){using var c=f.CreateConnection();return await c.ExecuteAsync("UPDATE Core.Assets SET DeletedAt=SYSUTCDATETIME() WHERE Id=@id AND UserId=@u AND DeletedAt IS NULL",new{id,u})==1;}}
